'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var hasProp = require( '@stdlib/assert/has-property' );
var isUndefined = require( '@stdlib/assert/is-undefined' );
var isObject = require( '@stdlib/assert/is-object' );
var Legend = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Legend, 'function', 'main export is a function' );
	t.end();
});

tape( 'the constructor returns an instance which has an `encode` property', function test( t ) {
	var v;

	v = new Legend({
		'fill': 'colorScale'
	});
	t.strictEqual( hasOwnProp( v, 'encode' ), false, 'returns expected value' );
	t.strictEqual( hasProp( v, 'encode' ), true, 'returns expected value' );
	t.strictEqual( isUndefined( v.encode ), true, 'returns expected value' );

	v = new Legend({
		'fill': 'colorScale',
		'encode': { 'labels': {} }
	});
	t.strictEqual( isObject( v.encode ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance having an `encode` property which throws an error if set to an invalid value', function test( t ) {
	var values;
	var i;

	values = [
		'beep',
		5,
		NaN,
		null,
		true,
		false,
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var legend = new Legend({
				'fill': 'colorScale'
			});
			legend.encode = value;
		};
	}
});

tape( 'the constructor returns an instance having an `encode` property', function test( t ) {
	var legend;

	legend = new Legend({
		'fill': 'colorScale'
	});
	t.strictEqual( isUndefined( legend.encode ), true, 'returns expected value' );

	legend = new Legend({
		'fill': 'colorScale',
		'encode': { 'labels': {} }
	});
	t.deepEqual( legend.encode, { 'labels': {} }, 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance having an `encode` property which can be set to a valid value', function test( t ) {
	var legend;

	legend = new Legend({
		'fill': 'colorScale'
	});

	legend.encode = { 'labels': {} };
	t.deepEqual( legend.encode, { 'labels': {} }, 'returns expected value' );

	legend.encode = { 'symbols': {} };
	t.deepEqual( legend.encode, { 'symbols': {} }, 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance which emits an event when the `encode` property is set to a new value', function test( t ) {
	var count;
	var legend;

	legend = new Legend({
		'fill': 'colorScale'
	});
	count = 0;

	legend.on( 'change', onChange );

	legend.encode = { 'labels': {} };
	t.strictEqual( count, 1, 'returns expected value' );

	legend.encode = { 'symbols': {} };
	t.strictEqual( count, 2, 'returns expected value' );

	// Setting to a different object always emits since objects are compared by reference:
	legend.encode = { 'symbols': {} };
	t.strictEqual( count, 3, 'returns expected value' );
	t.end();

	function onChange() {
		count += 1;
	}
});
